steps.sampleSolution:
type ProdutoDTO struct {
    Nome string `json:"nome" binding:"required"`
}
func criarProduto(c *gin.Context) {
    var dto ProdutoDTO
    if err := c.ShouldBindJSON(&dto); err != nil {
        c.JSON(400, gin.H{"erro": err.Error()})
        return
    }
    c.JSON(201, dto)
}
